// IconView renders svg sized to size×size DIPs tinted in color.
func IconView(c *ui.Context, svg *ui.SVG, size float32, color ui.Color) ui.Element {
	if svg == nil {
		return ui.Box(c).Size(size, size).Shrink(0)
	}
	return ui.Icon(c, svg).Size(size, size).TextColor(color).Shrink(0)
}
